const lines = csv.trim().split('\n').slice(1); // skip header
const byProduct = {};

lines.forEach(line => {
  const cols = line.split(',');
  const model = cols[0];
  const storage = cols[1];
  const color_en = cols[2];
  const estore = cols[4] === 'Y';
  const sku = cols[5];
  const gift1 = cols[8];
  const gift2 = cols[9];
  const gift3 = cols[10];
  const gift1Price = parseInt(cols[11]) || 0;
  const gift2Price = parseInt(cols[12]) || 0;
  const gift3Price = parseInt(cols[13]) || 0;

  if (!byProduct[model]) byProduct[model] = {};
  if (!byProduct[model][storage]) byProduct[model][storage] = { colors: [] };

  byProduct[model][storage].colors.push({
    name: color_en,
    sku: sku,
    gift1, gift2, gift3,
    gift1Price, gift2Price, gift3Price
  });
});

// Build final structure
const result = Object.entries(byProduct).map(([name, storages]) => {
  const storageOptions = Object.entries(storages).map(([storage, data]) => ({
    storage,
    price: 0, // price not in this sheet
    colors: data.colors
  }));
  return { name, storageOptions };
});

fs.writeFileSync('recommended-products.json', JSON.stringify(result, null, 2));
console.log('Rebuilt recommended-products.json with', result.length, 'products');
console.log(result.map(r => r.name));
